import { PDFDocument } from 'pdf-lib';
import { describe, expect, it } from 'vitest';
import { buildScanPdf } from './buildScanPdf';

const TALL = Uint8Array.from(
  atob(
    '',
  ),
  (c) => c.charCodeAt(0),
);
const WIDE = Uint8Array.from(
  atob(
    '',
  ),
  (c) => c.charCodeAt(0),
);

function readFile(file: File): Promise<ArrayBuffer> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result as ArrayBuffer);
    reader.onerror = () => reject(reader.error);
    reader.readAsArrayBuffer(file);
  });
}

describe('buildScanPdf', () => {
  it('makes one PDF page per photo, in order, portrait or landscape', async () => {
    const file = await buildScanPdf([TALL, WIDE, TALL]);
    expect(file.name).toBe('Scan.pdf');
    expect(file.type).toBe('application/pdf');
    const doc = await PDFDocument.load(await readFile(file));
    expect(doc.getPageCount()).toBe(3);
    const [first, second] = doc.getPages();
    expect(first!.getHeight()).toBeGreaterThan(first!.getWidth());
    expect(second!.getWidth()).toBeGreaterThan(second!.getHeight());
  });

  it('keeps every page inside A4', async () => {
    const file = await buildScanPdf([TALL]);
    const doc = await PDFDocument.load(await readFile(file));
    const page = doc.getPage(0);
    expect(page.getHeight()).toBeLessThanOrEqual(842.01);
    expect(page.getWidth()).toBeLessThanOrEqual(595.01);
  });

  it('refuses an empty scan', async () => {
    await expect(buildScanPdf([])).rejects.toThrow('no_pages');
  });
});
